document.addEventListener('DOMContentLoaded',()=>{const botoes=document.querySelectorAll('.btn-detalhes'),painel=document.getElementById('painel-detalhes'),titulo=document.getElementById('detalhe-titulo'),texto=document.getElementById('detalhe-texto'),btnFechar=document.getElementById('fechar-detalhes');botoes.forEach(botao=>{botao.addEventListener('click',(e)=>{const destino=e.target.getAttribute('data-destino'),informacao=e.target.getAttribute('data-info');titulo.textContent=`Detalhes sobre: ${destino}`,texto.textContent=informacao,painel.classList.remove('oculto'),painel.scrollIntoView({behavior:'smooth'})})}),btnFechar.addEventListener('click',()=>{painel.classList.add('oculto')})});